import { ApiProperty } from '@nestjs/swagger';
import { IsEnum } from 'class-validator';
import { FileCategory } from '../types/file.types.interface';

export class UploadFileDto {
  @ApiProperty({
    enum: FileCategory,
    description:
      'PROFILE_PHOTO (Class Master), ASSIGNMENT_ATTACHMENT (Teacher) or SUBMISSION (Student). REPORT files are generated by the server.',
  })
  @IsEnum(FileCategory)
  category: FileCategory;
}
